const inp = $workflow.input || {};
const src = inp.requestSource || 'AssignClaimsHandler';
const scenario = inp.scenario || 'Standard';
const claimReference = inp.claimReference || '';

const CASE_MANAGERS = {
  Standard: 'Sarah Whitmore, Northfield Rehabilitation Case Management',
  Displaced: 'Kevin Marsh, Apex Major Injury Case Management',
  Underinsured: 'Rebecca Nolan, Northfield Rehabilitation Case Management',
  Investigated: 'Ian Prescott, Meridian Medico-Legal Services',
  Declined: 'Sarah Whitmore, Northfield Rehabilitation Case Management',
  Reopened: 'Rebecca Nolan, Northfield Rehabilitation Case Management'
};

const TREATMENT_PROVIDERS = {
  Standard: 'Clearwater Physiotherapy Ltd',
  Displaced: 'Redline Neurorehabilitation Ltd',
  Underinsured: 'Clearwater Physiotherapy Ltd',
  Investigated: 'Clearwater Physiotherapy Ltd',
  Reopened: 'Ashgrove Orthopaedic Rehabilitation Group',
  Declined: 'Clearwater Physiotherapy Ltd'
};

const CARE_PACKAGE = {
  Standard: 0,
  Displaced: 4500,
  Underinsured: 0,
  Investigated: 0,
  Declined: 0,
  Reopened: 0
};

const caseManager = CASE_MANAGERS[scenario] || CASE_MANAGERS.Standard;
const treatmentProvider = TREATMENT_PROVIDERS[scenario] || TREATMENT_PROVIDERS.Standard;
const carePackageAmount = (CARE_PACKAGE[scenario] !== undefined) ? CARE_PACKAGE[scenario] : CARE_PACKAGE.Standard;
const hiddenDamageFound = (scenario === 'Reopened');

const out = {
  claimStatus: '',
  hiddenDamageFound: false,
  reserveCareAndRehab: 0,
  explanation: ''
};

if (src === 'AssignClaimsHandler') {
  out.claimStatus = 'Case Manager Allocated - ' + caseManager;
  out.explanation = 'Rehabilitation case manager ' + caseManager + ' allocated to claim ' + (claimReference || '(unspecified)') + '.';
} else if (src === 'AuthoriseTreatmentPlan') {
  out.claimStatus = 'Treatment Authorised - ' + treatmentProvider;
  out.explanation = 'Initial treatment plan authorised and ' + treatmentProvider + ' instructed on claim ' + (claimReference || '(unspecified)') + '.';
} else if (src === 'HiddenDamageInspection') {
  out.hiddenDamageFound = hiddenDamageFound;
  out.claimStatus = hiddenDamageFound ? 'Further Injury Identified - Re-assessment Required' : 'Medical Examination Clear';
  out.explanation = hiddenDamageFound ? 'The independent medical examination identified an injury not covered by the original prognosis; the claim is being sent back for re-assessment of quantum.' : 'The independent medical examination found no injury beyond the original prognosis; recovery is on track.';
} else if (src === 'AssignRehabProvider') {
  out.claimStatus = 'Medical Examiner Allocated - ' + treatmentProvider;
  out.explanation = treatmentProvider + ' instructed to provide the independent medical examination and treatment for claim ' + (claimReference || '(unspecified)') + '.';
} else if (src === 'ArrangeCareSupport') {
  out.reserveCareAndRehab = carePackageAmount;
  out.claimStatus = (carePackageAmount > 0) ? 'Care Package Arranged' : 'Care Package Not Required';
  out.explanation = (carePackageAmount > 0) ? ('Daily care and support package arranged with a reserve of ' + carePackageAmount + '.') : 'The claimant can manage unaided, so no care package was arranged.';
} else {
  out.claimStatus = 'UnknownRequestSource';
  out.explanation = 'Unrecognised requestSource: ' + src + '.';
}

return out;
